def spiral_fill(I,N=20):
 h,w=I.shape; O=np.full((N,N),-1);O[:h,:w]=I
 for r in range(N):
  for c in range(N):
   rr,cc=r,c
   for k in range(4):
    if rr<h and cc<w:
     O[r,c]=I[rr,cc];break
    rr,cc=cc,N-1-rr
 return O
